import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Navigate } from 'react-router-dom';
import { Container, Row, Col } from 'react-bootstrap';
import ProductCard from './card';
import SearchBar from './SearchBar'; // Import the SearchBar component
import useAuth from './hooks/authHook'; // Assuming this handles authentication status
import './ProductCard.css';

const Homepage = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchText, setSearchText] = useState(''); // State for the search input

  // Check if the user is authenticated using the custom hook
  const isAuthenticated = useAuth();

  // Fetch products from the API
  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await axios.get('http://localhost:5001/product/');
        setProducts(response.data);
      } catch (error) {
        setError(error.message);
      } finally {
        setLoading(false);
      }
    };

    if (isAuthenticated) {
      fetchProducts();
    }
  }, [isAuthenticated]);

  // Redirect to login if not authenticated
  if (!isAuthenticated) {
    return <Navigate to="/login" />;
  }

  // Filter products based on search text
  const filteredProducts = products.filter(product => 
    product.name.toLowerCase().includes(searchText.toLowerCase()) || 
    product.description.toLowerCase().includes(searchText.toLowerCase())
  );

  // Loading or error states
  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  return (
    <Container>
      <h2>Welcome to the Product Page</h2>

      {/* Render search bar only if the user is authenticated */}
      {isAuthenticated && (
        <SearchBar searchText={searchText} setSearchText={setSearchText} />
      )}

      {/* Display filtered products */}
      <Row>
        {filteredProducts.map((product) => (
          <Col key={product.product_id} sm={12} md={6} lg={4}>
            <ProductCard product={product} />
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default Homepage;
